final class CartTests: XCTestCase {
  private static let suiteName = "CartTests"
  private var sut: Cart!
  private var defaults: UserDefaults!

  override func setUpWithError() throws {
    try super.setUpWithError()
    // A private suite, not .standard — nothing bleeds into the next test
    defaults = UserDefaults(suiteName: Self.suiteName)
    defaults.removePersistentDomain(forName: Self.suiteName)
    sut = Cart(defaults: defaults)
  }

  override func tearDownWithError() throws {
    defaults.removePersistentDomain(forName: Self.suiteName)
    sut = nil        // XCTest still retains `self` until the run ends
    defaults = nil
    try super.tearDownWithError()
  }

  func testAddingItemStoresIt() {
    sut.add(Item(id: "a"))
    XCTAssertEqual(sut.items.count, 1)
  }

  // WRONG — a static is not reset by the fresh instance
  private static var callCount = 0
  func testOrderDependent() {
    Self.callCount += 1
    XCTAssertEqual(Self.callCount, 1)   // green alone, red after any sibling
  }

  // RIGHT — the observer is removed where it was added
  func testObserverDoesNotOutliveTheTest() {
    let token = NotificationCenter.default.addObserver(
      forName: .cartChanged, object: nil, queue: nil
    ) { _ in }
    addTeardownBlock { NotificationCenter.default.removeObserver(token) }

    sut.add(Item(id: "b"))
    XCTAssertEqual(sut.items.count, 1)
  }
}

