// WRONG — deadlocks: the blocking wait owns the thread the callback needs
func testRefreshes() async {
  let exp = expectation(description: "refreshed")
  sut.refresh { exp.fulfill() }
  wait(for: [exp], timeout: 1.0)      // never returns in an async test
}

// RIGHT — the async wait suspends instead of blocking
func testRefreshesAsync() async {
  let exp = expectation(description: "refreshed")
  exp.expectedFulfillmentCount = 1
  exp.assertForOverFulfill = true     // a second callback is a failure

  sut.refresh { exp.fulfill() }
  await fulfillment(of: [exp], timeout: 1.0)
  XCTAssertEqual(sut.items.count, 3)
}

// BETTER — no expectation at all: bridge the callback once
extension Loader {
  func refreshed() async -> [Item] {
    await withCheckedContinuation { continuation in
      refresh { continuation.resume(returning: $0) }
    }
  }
}

func testRefreshedValue() async {
  let items = await sut.refreshed()
  XCTAssertEqual(items.count, 3)
}

