// 1. Hand-written fake: conforms, records, returns what the test needs
protocol ProfileLoading {
  func profile(id: String) async throws -> Profile
}

final class ProfileLoaderSpy: ProfileLoading {
  private(set) var requestedIDs: [String] = []
  var result: Result<Profile, Error> = .success(.stub)

  func profile(id: String) async throws -> Profile {
    requestedIDs.append(id)
    return try result.get()
  }
}

@Test func loadsTheProfileOnce() async {
  let loader = ProfileLoaderSpy()
  let sut = ProfileViewModel(loader: loader)

  await sut.load(id: "42")

  // Assert the observable behaviour, plus the one call that matters
  #expect(loader.requestedIDs == ["42"])
  #expect(sut.state == .loaded(.stub))
}

// 2. Struct of closures: no protocol, override exactly one thing
struct ProfileClient {
  var profile: (String) async throws -> Profile

  static let live = ProfileClient(profile: { id in
    try await api.profile(id: id)
  })
}

@Test func showsErrorWhenOffline() async {
  var client = ProfileClient.live
  client.profile = { _ in throw LoadError.offline }   // per-test override
  let sut = ProfileViewModel(client: client)

  await sut.load(id: "42")

  #expect(sut.state == .failed(.offline))
}

@MainActor
@Observable
final class ProfileViewModel {
  private(set) var state: State = .idle
  private let loader: ProfileLoading
  private(set) var loadTask: Task<Void, Never>?

  init(loader: ProfileLoading) { self.loader = loader }

  // Fire-and-forget: returns before the body has run at all
  func loadFireAndForget() {
    loadTask = Task { state = .loaded(try? await loader.profile(id: "42")) }
  }

  // Awaitable: the caller — and the test — control when it is done
  func load() async {
    state = .loading
    state = .loaded(try? await loader.profile(id: "42"))
  }
}

@MainActor
final class ProfileViewModelTests: XCTestCase {
  // WRONG — asserts before the Task body ever ran
  func testLoadsBroken() {
    let sut = ProfileViewModel(loader: ProfileLoaderSpy())
    sut.loadFireAndForget()
    XCTAssertEqual(sut.state, .loaded(.stub))   // still .idle
  }

  // RIGHT — await the work itself, no sleeping and no yielding
  func testLoads() async {
    let sut = ProfileViewModel(loader: ProfileLoaderSpy())
    await sut.load()
    XCTAssertEqual(sut.state, .loaded(.stub))
  }

  // Acceptable when the fire-and-forget call has to stay
  func testLoadsViaHandle() async {
    let sut = ProfileViewModel(loader: ProfileLoaderSpy())
    sut.loadFireAndForget()
    await sut.loadTask?.value
    XCTAssertEqual(sut.state, .loaded(.stub))
  }
}

final class AnalyticsSpy: AnalyticsTracking {
  private(set) var events: [Event] = []
  var onTrack: ((Event) -> Void)?

  func track(_ event: Event) {
    events.append(event)
    onTrack?(event)
  }
}

