// Only when the absence is genuinely async: keep the timeout near the delay
func testDebounceDoesNotFireEarly() async {
  let spy = AnalyticsSpy()
  let sut = SearchViewModel(analytics: spy, debounce: .milliseconds(300))

  let never = expectation(description: "no search event")
  never.isInverted = true
  spy.onTrack = { if $0.name == "search" { never.fulfill() } }

  sut.typed("fl")
  await fulfillment(of: [never], timeout: 0.2)   // costs 0.2s, not 5s
}

// The paired positive test, without which the negative one proves nothing
func testDebounceEventuallyFires() async {
  let spy = AnalyticsSpy()
  let sut = SearchViewModel(analytics: spy, debounce: .milliseconds(300))

  let fired = expectation(description: "search event")
  spy.onTrack = { if $0.name == "search" { fired.fulfill() } }

  sut.typed("flutter")
  await fulfillment(of: [fired], timeout: 1.0)
}

