final class ProfileHeaderSnapshotTests: XCTestCase {
  // CI and local runs must use the same destination:
  // xcodebuild test -destination 'platform=iOS Simulator,name=iPhone 16,OS=18.4'

  override func invokeTest() {
    // A missing snapshot fails instead of recording itself green
    withSnapshotTesting(record: .never, diffTool: .ksdiff) {
      super.invokeTest()
    }
  }

  private func makeView() -> some View {
    // Inputs frozen: no Date(), no network image, no random ordering
    ProfileHeader(
      user: .stub,
      joined: Date(timeIntervalSince1970: 1_700_000_000),
      imageLoader: .stubbed(.avatarFixture)
    )
  }

  func testLightAndDark() {
    let view = makeView()

    assertSnapshot(
      of: view,
      as: .image(
        precision: 0.99,            // tolerate a few stray pixels
        perceptualPrecision: 0.98,  // tolerate antialiasing differences
        layout: .device(config: .iPhone13),
        traits: .init(userInterfaceStyle: .light)
      ),
      named: "light"
    )

    assertSnapshot(
      of: view,
      as: .image(
        precision: 0.99,
        perceptualPrecision: 0.98,
        layout: .device(config: .iPhone13),
        traits: .init(userInterfaceStyle: .dark)
      ),
      named: "dark"
    )
  }
}

