// Baseline is stored at
// MyApp.xcodeproj/xcshareddata/xcbaselines/<uuid>.xcbaseline/Info.plist
// keyed by device model + OS — record it on the machine CI actually uses.
final class LaunchPerformanceTests: XCTestCase {

  // UI test target: the metric spans process start -> first frame.
  func testColdLaunch() throws {
    let options = XCTMeasureOptions()
    options.iterationCount = 10                 // more samples, tighter deviation

    measure(metrics: [XCTApplicationLaunchMetric()], options: options) {
      XCUIApplication().launch()
    }
  }

  // Measure a region you own, without paying for the setup around it
  func testFeedFirstPage() throws {
    let app = XCUIApplication()
    let options = XCTMeasureOptions()
    options.invocationOptions = [.manuallyStart]

    let metric = XCTOSSignpostMetric(subsystem: "com.shop.feed",
                                     category: "render",
                                     name: "first-page")

    measure(metrics: [metric], options: options) {
      app.launchArguments = ["-uiTesting"]
      app.launch()
      startMeasuring()                          // everything above is excluded
      app.buttons["feed.refresh"].tap()
      XCTAssertTrue(app.cells.firstMatch.waitForExistence(timeout: 10))
    }
  }
}

