// RIGHT — wait for the condition, not for the clock
final class CheckoutUITests: XCTestCase {
  private var app: XCUIApplication!

  override func setUp() {
    continueAfterFailure = false
    app = XCUIApplication()
    app.launchArguments = ["-uiTesting", "-disableAnimations"]
    app.launch()
  }

  override func tearDown() {
    guard let run = testRun, run.failureCount > 0 else { return }
    let shot = XCTAttachment(screenshot: XCUIScreen.main.screenshot())
    shot.lifetime = .keepAlways               // survives a later green rerun
    add(shot)
  }

  func testPay() {
    let pay = app.buttons["checkout.pay"]
    XCTAssertTrue(pay.waitForExistence(timeout: 10))

    // hittable, not merely present: it may still be sliding in
    let ready = expectation(for: NSPredicate(format: "isHittable == true"),
                            evaluatedWith: pay)
    wait(for: [ready], timeout: 10)
    pay.tap()

    XCTAssertTrue(
      app.staticTexts["order.confirmation"].waitForExistence(timeout: 15))
  }
}

// The rule lives in the model — the part worth a fast test
@Observable
final class CartModel {
  private(set) var items: [Item] = []
  var isSubmitting = false

  var canBuy: Bool { !items.isEmpty && !isSubmitting }

  func add(_ item: Item) { items.append(item) }
  func submit() { isSubmitting = true }
}

@Test func buyIsBlockedUntilSomethingIsInTheCart() {
  let model = CartModel()
  #expect(model.canBuy == false)

  model.add(Item(price: 100))
  #expect(model.canBuy == true)

  model.isSubmitting = true
  #expect(model.canBuy == false)        // the case that actually shipped broken
}

// The view is now a wire, not a rule
