@Test func expiredReceiptIsReported() async throws {
  let config = URLSessionConfiguration.ephemeral
  config.protocolClasses = [StubURLProtocol.self]     // no URLSession protocol needed
  let spy = AnalyticsSpy()

  let sut = ReceiptPresenter(session: URLSession(configuration: config),
                             analytics: spy,
                             defaults: UserDefaults(suiteName: #function)!,
                             now: { .distantFuture })  // deterministic clock

  _ = try await sut.load(id: "r1")
  #expect(spy.events == [.receiptShown(expired: true)])
